+      const status = response.body?.status;
+      if (status === "succeeded") return;
+      if (status === "failed") {
+        throw withRedactedErrorMessage("Meilisearch task failed", response.body?.error?.message ?? "unknown");
+      }
+      await new Promise((resolve) => setTimeout(resolve, 50));
+    }

